import{H as e,gt as t,nt as n,tt as r}from"./chunks/framework.sms2Rnvf.js";var i=JSON.parse(`{"title":"Shortcuts","description":"","frontmatter":{},"headers":[],"relativePath":"reporting/shortcuts.md","filePath":"reporting/shortcuts.md","lastUpdated":1781102819000}`),a={name:`reporting/shortcuts.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<div style="display:none;" hidden="true" aria-hidden="true" data-nosnippet>Are you an LLM? You can read better optimized documentation at /reporting/shortcuts.md for this page in Markdown format</div><h1 id="shortcuts" tabindex="-1">Shortcuts <a class="header-anchor" href="#shortcuts" aria-label="Permalink to “Shortcuts”">​</a></h1><p>Below is a list of shortcuts that SysReptor currently supports.</p><h2 id="project-shortcuts" tabindex="-1">Project shortcuts <a class="header-anchor" href="#project-shortcuts" aria-label="Permalink to “Project shortcuts”">​</a></h2><p>These shortcuts work in SysReptor projects, including findings, sections and notes.</p><ul><li><code>CTRL + Z</code> - Undo</li><li><code>CTRL + SHIFT + Z</code> / <code>CTRL + Y</code> - Redo</li><li><code>CTRL + S</code> - Save design/template</li><li><code>CTRL + SHIFT + F</code> - Search in all notes/findings/sections</li><li><code>CTRL + J</code> - Create a new note/finding</li><li><code>CTRL + ALT + M</code> - Create comment</li></ul><p>Multi-select in the reporting sidebar (findings, sections) and note tree:</p><ul><li><code>CLICK</code> - Select item and navigate</li><li><code>CTRL + CLICK</code> - Toggle item in multi-selection</li><li><code>SHIFT + CLICK</code> - Select range from last clicked item to current item</li></ul><h2 id="markdown-shortcuts" tabindex="-1">Markdown shortcuts <a class="header-anchor" href="#markdown-shortcuts" aria-label="Permalink to “Markdown shortcuts”">​</a></h2><p>These shortcuts work while editing <a href="/reporting/markdown-features">markdown</a> in report fields, text notes, and other markdown editors.</p><ul><li><code>CTRL + B</code> - Bold</li><li><code>CTRL + I</code> - Italic</li><li><code>CTRL + E</code> - Inline code</li><li><code>CTRL + K</code> - Link</li><li><code>TAB</code> / <code>SHIFT + TAB</code> - Indent / outdent</li><li><code>CTRL + [</code> / <code>CTRL + ]</code> - Decrease / increase indent</li><li><code>ALT + LEFT MOUSE</code> - Multi-line select</li><li><code>SHIFT + ALT + UP/DOWN ARROW</code> - Duplicate line</li><li><code>ALT + UP/DOWN ARROW</code> - Move line up/down</li><li><code>ALT + LEFT/RIGHT ARROW</code> - Jump to the next markdown element</li><li><code>ALT + I</code> - Select line</li><li><code>CTRL + SHIFT + K</code> - Delete line</li><li><code>SHIFT + ALT + A</code> - Add/remove HTML content</li><li><code>CTRL + F</code> - Open search panel</li><li><code>F3</code> / <code>CTRL + G</code> - Find next (in search panel)</li><li><code>SHIFT + F3</code> / <code>SHIFT + CTRL + G</code> - Find previous (in search panel)</li><li><code>ESCAPE</code> - Close search panel</li></ul><h2 id="image-editor-shortcuts" tabindex="-1">Image Editor shortcuts <a class="header-anchor" href="#image-editor-shortcuts" aria-label="Permalink to “Image Editor shortcuts”">​</a></h2><p>These shortcuts work in the <a href="/reporting/image-editor">image editor</a>.</p><ul><li><code>V</code> - Select and move</li><li><code>R</code> - Rectangle (outline)</li><li><code>SHIFT + R</code> - Rectangle (filled)</li><li><code>P</code> - Pixelate</li><li><code>O</code> - Ellipse</li><li><code>L</code> - Line</li><li><code>T</code> - Text</li><li><code>M</code> - Numbered marker</li><li><code>DELETE</code> / <code>BACKSPACE</code> - Delete selected object(s)</li><li><code>CTRL + MOUSE WHEEL</code> - Zoom in/out</li></ul><h2 id="excalidraw-shortcuts" tabindex="-1">Excalidraw shortcuts <a class="header-anchor" href="#excalidraw-shortcuts" aria-label="Permalink to “Excalidraw shortcuts”">​</a></h2><p>These shortcuts work in <a href="/reporting/notes#note-types">Excalidraw notes</a>.</p><p>Press <code>?</code> or open <strong>Help</strong> from the Excalidraw menu for the full shortcut reference.</p><p><strong>Tools</strong></p><ul><li><code>V</code> / <code>1</code> - Selection</li><li><code>R</code> / <code>2</code> - Rectangle</li><li><code>D</code> / <code>3</code> - Diamond</li><li><code>O</code> / <code>4</code> - Ellipse</li><li><code>A</code> / <code>5</code> - Arrow</li><li><code>L</code> / <code>6</code> - Line</li><li><code>P</code> / <code>7</code> - Draw</li><li><code>T</code> / <code>8</code> - Text</li><li><code>9</code> - Image (when image upload is available)</li><li><code>E</code> / <code>0</code> - Eraser</li><li><code>F</code> - Frame</li><li><code>H</code> - Hand (pan)</li><li><code>K</code> - Laser pointer</li><li><code>Q</code> - Lock tool</li></ul><p><strong>View</strong></p><ul><li><code>CTRL + +</code> / <code>CTRL + -</code> / <code>CTRL + 0</code> - Zoom in / out / reset</li><li><code>SHIFT + 1</code> / <code>SHIFT + 2</code> - Zoom to fit canvas / zoom to fit selection</li><li><code>SPACE + DRAG</code> / <code>WHEEL + DRAG</code> - Pan canvas</li><li><code>ALT + Z</code> - Zen mode</li><li><code>ALT + S</code> - Toggle object snapping</li><li><code>CTRL + &#39;</code> - Toggle grid</li><li><code>CTRL + F</code> - Search</li><li><code>CTRL + /</code> / <code>CTRL + SHIFT + P</code> - Command palette</li></ul><p><strong>Editor</strong></p><ul><li><code>CTRL + Z</code> - Undo</li><li><code>CTRL + SHIFT + Z</code> / <code>CTRL + Y</code> - Redo</li><li><code>CTRL + C</code> / <code>CTRL + X</code> / <code>CTRL + V</code> - Copy / cut / paste</li><li><code>CTRL + D</code> - Duplicate selection</li><li><code>CTRL + A</code> - Select all</li><li><code>SHIFT + CLICK</code> - Multi-select</li><li><code>CTRL + CLICK</code> - Deep select</li><li><code>CTRL + DRAG</code> - Deep box select</li><li><code>DELETE</code> - Delete selection</li><li><code>CTRL + G</code> / <code>CTRL + SHIFT + G</code> - Group / ungroup</li><li><code>CTRL + [</code> / <code>CTRL + ]</code> - Send backward / bring forward</li><li><code>CTRL + SHIFT + [</code> / <code>CTRL + SHIFT + ]</code> - Send to back / bring to front</li><li><code>CTRL + K</code> - Add / edit link</li></ul><h2 id="ai-agent-shortcuts" tabindex="-1">AI Agent shortcuts <a class="header-anchor" href="#ai-agent-shortcuts" aria-label="Permalink to “AI Agent shortcuts”">​</a></h2><p>These shortcuts work in the <a href="/reporting/ai-agent">AI Agent</a> chat sidebar.</p><ul><li><code>CTRL + L</code> - Start new chat</li><li><code>ENTER</code> - Send message</li><li><code>SHIFT + ENTER</code> - New line in message input</li></ul>`,26)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};